package main

import (
	"encoding/json"
	"os"
	"gopkg.in/yaml.v3"
)

func main() {
	var v interface{}
	dec := json.NewDecoder(os.Stdin)
	dec.UseNumber()
	if err := dec.Decode(&v); err != nil { panic(err) }
	// convert to yaml nodes preserving order via sequential map
	m := v.(map[string]interface{})
	// sort keys by s-number for readability
	keys := []string{}
	for k := range m { keys = append(keys, k) }
	// simple ordering by numeric suffix
	for i := 0; i < len(keys); i++ { for j := i+1; j < len(keys); j++ { if less(keys[j], keys[i]) { keys[i], keys[j] = keys[j], keys[i] } } }
	n := &yaml.Node{Kind: yaml.MappingNode}
	for _, k := range keys {
		kn := &yaml.Node{Kind: yaml.ScalarNode, Value: k}
		var vn yaml.Node
		s := m[k]
		if js, ok := s.(json.Number); ok { s = js.String() }
		vn.Encode(s)
		n.Content = append(n.Content, kn, &vn)
	}
	enc := yaml.NewEncoder(os.Stdout)
	enc.SetIndent(2)
	enc.Encode(n)
}
func less(a, b string) bool {
	var x, y int
	for _, c := range a[1:] { x = x*10 + int(c-'0') }
	for _, c := range b[1:] { y = y*10 + int(c-'0') }
	return x < y
}
EOF
