mkdir -p order && cat > order/order.go <<'EOF'
// Package order provides an insertion-ordered map representation used as the
// common in-memory model for every supported document format.
package order

import (
	"bytes"
	"encoding/json"
	"math"
)

// MapItem is a single key/value pair of a MapSlice.
type MapItem struct {
	Key interface{}
	Val interface{}
}

// MapSlice is an ordered list of key/value pairs.
type MapSlice []MapItem

// Get returns the value stored under key and whether it was present.
func (m MapSlice) Get(key interface{}) (interface{}, bool) {
	for _, item := range m {
		if item.Key == key {
			return item.Val, true
		}
	}
	return nil, false
}

// Index returns the position of the first item with the given key, or -1.
func (m MapSlice) Index(key interface{}) int {
	for i, item := range m {
		if item.Key == key {
			return i
		}
	}
	return -1
}

// Delete removes every item with the given key.
func (m MapSlice) Delete(key interface{}) MapSlice {
	out := m[:0]
	for _, item := range m {
		if item.Key != key {
			out = append(out, item)
		}
	}
	return out
}

// JSONOptions controls how a tree is serialized to JSON.
type JSONOptions struct {
	// EscapeHTML enables escaping of <, > and & in strings.
	EscapeHTML bool
	// Indent enables two space indentation of the output.
	Indent bool
	// KeepSpecialFloats, when false, converts +Inf, -Inf and NaN into the
	// strings "Infinity", "-Infinity" and "NaN". When true, infinities are
	// clamped to the largest finite float and NaN becomes null.
	KeepSpecialFloats bool
}

// MarshalJSON implements json.Marshaler, writing the pairs in order.
func (m MapSlice) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, item := range m {
		if i > 0 {
			buf.WriteByte(',')
		}
		key, err := jsonKey(item.Key)
		if err != nil {
			return nil, err
		}
		buf.Write(key)
		buf.WriteByte(':')
		val, err := json.Marshal(item.Val)
		if err != nil {
			return nil, err
		}
		buf.Write(val)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func jsonKey(key interface{}) ([]byte, error) {
	s, ok := key.(string)
	if !ok {
		b, err := json.Marshal(key)
		if err != nil {
			return nil, err
		}
		if len(b) > 0 && b[0] == '"' {
			return b, nil
		}
		s = string(b)
	}
	return json.Marshal(s)
}

// NormalizeFloats walks the tree and replaces special float values so that
// the standard JSON encoder can handle them.
func NormalizeFloats(v interface{}, keep bool) interface{} {
	switch t := v.(type) {
	case MapSlice:
		out := make(MapSlice, len(t))
		for i, item := range t {
			out[i] = MapItem{Key: NormalizeFloats(item.Key, keep), Val: NormalizeFloats(item.Val, keep)}
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = NormalizeFloats(e, keep)
		}
		return out
	case float64:
		switch {
		case math.IsInf(t, 1):
			if keep {
				return math.MaxFloat64
			}
			return "Infinity"
		case math.IsInf(t, -1):
			if keep {
				return -math.MaxFloat64
			}
			return "-Infinity"
		case math.IsNaN(t):
			if keep {
				return nil
			}
			return "NaN"
		}
	}
	return v
}
EOF
echo ok"}

