package convert

import (
	"bytes"
	"encoding/json"
	"io"

	"gopkg.in/yaml.v3"

	"yj/order"
)

// JSON converts between the generic ordered tree and JSON documents.
type JSON struct {
	// EscapeHTML enables escaping of <, > and & in the output.
	EscapeHTML bool
	// Indent enables pretty printing of the output.
	Indent bool
	// KeepSpecialFloats keeps +Inf, -Inf and NaN as numbers (clamped) instead
	// of converting them to strings.
	KeepSpecialFloats bool
}

// Decode validates the JSON document in r and converts it. The document is
// interpreted with YAML semantics, since JSON is a subset of YAML, which keeps
// numeric handling consistent across formats.
func (j JSON) Decode(r io.Reader) (interface{}, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	var raw json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	var node yaml.Node
	if err := yaml.NewDecoder(bytes.NewReader(data)).Decode(&node); err != nil {
		if err == io.EOF {
			return nil, ErrEmptyDocument
		}
		return nil, err
	}
	d := &yamlDecoder{aliases: map[*yaml.Node]bool{}}
	return d.node(&node)
}

// Encode writes v as JSON.
func (j JSON) Encode(w io.Writer, v interface{}) error {
	v = order.NormalizeFloats(v, j.KeepSpecialFloats)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(j.EscapeHTML)
	if j.Indent {
		enc.SetIndent("", "  ")
	}
	return enc.Encode(v)
}
