cat > main.go <<'EOF'
// Command yj converts between YAML, TOML, JSON and HCL while preserving the
// order of object keys.
package main

import (
	"fmt"
	"io"
	"os"
	"strings"

	"yj/convert"
)

const version = "v0.0.0"

const usageText = `Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`

type format int

const (
	formatYAML format = iota
	formatTOML
	formatJSON
	formatHCL
)

func (f format) String() string {
	switch f {
	case formatYAML:
		return "YAML"
	case formatTOML:
		return "TOML"
	case formatJSON:
		return "JSON"
	case formatHCL:
		return "HCL"
	}
	return "unknown"
}

type options struct {
	formats     []format
	noSpecial   bool
	escapeHTML  bool
	indent      bool
	parseKeys   bool
	help        bool
	showVersion bool
	invalid     []string
}

func parseArgs(args []string) options {
	var o options
	for _, arg := range args {
		for _, c := range arg {
			switch c {
			case '-', ' ', '\t':
			case 'y':
				o.formats = append(o.formats, formatYAML)
			case 't':
				o.formats = append(o.formats, formatTOML)
			case 'j':
				o.formats = append(o.formats, formatJSON)
			case 'c':
				o.formats = append(o.formats, formatHCL)
			case 'r':
				o.formats = append(o.formats, formatJSON, formatYAML)
			case 'n':
				o.noSpecial = true
			case 'e':
				o.escapeHTML = true
			case 'i':
				o.indent = true
			case 'k':
				o.parseKeys = true
			case 'h':
				o.help = true
			case 'v':
				o.showVersion = true
			default:
				o.invalid = append(o.invalid, string(c))
			}
		}
	}
	return o
}

func (o options) fromTo() (format, format) {
	switch len(o.formats) {
	case 0:
		return formatYAML, formatJSON
	case 1:
		return o.formats[0], formatJSON
	}
	return o.formats[len(o.formats)-2], o.formats[len(o.formats)-1]
}

func usage(w io.Writer) {
	fmt.Fprintf(w, usageText, os.Args[0])
}

func main() {
	os.Exit(run(os.Stdin, os.Stdout, os.Stderr, os.Args[1:]))
}

func run(stdin io.Reader, stdout, stderr io.Writer, args []string) int {
	o := parseArgs(args)
	if len(o.invalid) > 0 {
		usage(stderr)
		fmt.Fprintf(stderr, "Error: invalid flags specified: %s\n", strings.Join(o.invalid, " "))
		return 1
	}
	from, to := o.fromTo()
	if o.parseKeys && to != formatYAML {
		usage(stderr)
		fmt.Fprintln(stderr, "Error: flag -k only valid for YAML output")
		return 1
	}
	if o.escapeHTML && to != formatJSON {
		usage(stderr)
		fmt.Fprintln(stderr, "Error: flag -e only valid for JSON output")
		return 1
	}
	if o.indent && to != formatJSON && to != formatTOML {
		usage(stderr)
		fmt.Fprintln(stderr, "Error: flag -i only valid for JSON or TOML output")
		return 1
	}
	if o.help {
		usage(stdout)
		return 0
	}
	if o.showVersion {
		fmt.Fprintln(stdout, version)
		return 0
	}

	var value interface{}
	var err error
	switch from {
	case formatYAML:
		value, err = convert.YAML{KeepSpecialFloats: o.noSpecial}.Decode(stdin)
	case formatTOML:
		value, err = convert.TOML{KeepSpecialFloats: o.noSpecial}.Decode(stdin)
	case formatJSON:
		value, err = convert.JSON{KeepSpecialFloats: o.noSpecial}.Decode(stdin)
	case formatHCL:
		value, err = convert.HCL{}.Decode(stdin)
	}
	if err == convert.ErrEmptyDocument {
		return 0
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error parsing %s: %s\n", from, err)
		return 1
	}

	switch to {
	case formatYAML:
		err = convert.YAML{KeepSpecialFloats: o.noSpecial, ParseKeys: o.parseKeys}.Encode(stdout, value)
	case formatTOML:
		err = convert.TOML{KeepSpecialFloats: o.noSpecial, Indent: o.indent}.Encode(stdout, value)
	case formatJSON:
		err = convert.JSON{EscapeHTML: o.escapeHTML, Indent: o.indent, KeepSpecialFloats: o.noSpecial}.Encode(stdout, value)
	case formatHCL:
		err = convert.HCL{}.Encode(stdout, value)
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error writing %s: %s\n", to, err)
		return 1
	}
	return 0
}
