#!/usr/bin/env python3
"""Compare two binaries on a list of (args, stdin) cases."""
import subprocess, sys, json

def run(binary, args, data):
    r = subprocess.run([binary] + args, input=data, capture_output=True)
    return r.returncode, r.stdout, r.stderr

def compare(orig, mine, cases, show_ok=False):
    nd = 0
    for args, data in cases:
        if isinstance(data, str): data = data.encode()
        a = run(orig, args, data)
        b = run(mine, args, data)
        # normalize usage program name
        bo = b[2].replace(mine.encode(), orig.encode())
        b = (b[0], b[1].replace(mine.encode(), orig.encode()), bo)
        if a != b:
            nd += 1
            print("=== CASE args=%r input=%r" % (args, data[:300]))
            if a[0] != b[0]: print("  rc: orig=%d mine=%d" % (a[0], b[0]))
            if a[1] != b[1]: print("  stdout orig: %r\n  stdout mine: %r" % (a[1][:500], b[1][:500]))
            if a[2] != b[2]: print("  stderr orig: %r\n  stderr mine: %r" % (a[2][:500], b[2][:500]))
        elif show_ok:
            print("ok", args, data[:60])
    print("diffs: %d of %d" % (nd, len(cases)))
    return nd

if __name__ == '__main__':
    orig, mine, casefile = sys.argv[1], sys.argv[2], sys.argv[3]
    cases = json.load(open(casefile))
    compare(orig, mine, [(c[0], c[1]) for c in cases])
