// YAML converts between the generic ordered tree and YAML documents.
type YAML struct {
	// KeepSpecialFloats disables conversion between the strings
	// "Infinity", "-Infinity", "NaN" and the matching float values.
	KeepSpecialFloats bool
	// ParseKeys attempts to interpret string keys as JSON values when encoding.
	ParseKeys bool
	// RestoreInfinities converts the largest finite floats found in parsed
	// keys back into infinities. It only applies when both KeepSpecialFloats
	// and ParseKeys are set, and is used when the input was also YAML, so
	// that the clamping applied to keys while decoding is undone.
	RestoreInfinities bool
}

// ErrEmptyDocument is returned when the input stream contains no document.
var ErrEmptyDocument = errors.New("empty document")

// Decode reads the first YAML document from r and converts it.
func (y YAML) Decode(r io.Reader) (interface{}, error) {
	var node yaml.Node
	if err := yaml.NewDecoder(r).Decode(&node); err != nil {
		if err == io.EOF {
			return nil, ErrEmptyDocument
		}
		return nil, err
	}
	d := &yamlDecoder{aliases: map[*yaml.Node]bool{}, keepSpecial: y.KeepSpecialFloats}
	return d.node(&node)
}

type yamlDecoder struct {
	aliases     map[*yaml.Node]bool
	keepSpecial bool
}

func (d *yamlDecoder) node(n *yaml.Node) (interface{}, error) {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil, nil
		}
		return d.node(n.Content[0])
	case yaml.MappingNode:
		return d.mapping(n)
	case yaml.SequenceNode:
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := d.node(c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.AliasNode:
		if d.aliases[n] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Value)
		}
		d.aliases[n] = true
		v, err := d.node(n.Alias)
		delete(d.aliases, n)
		return v, err
	case yaml.ScalarNode:
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return nil, fmt.Errorf("scalar decode error: %s", err)
		}
		return v, nil
	}
	return nil, fmt.Errorf("unknown node kind: %d", n.Kind)
}

func (d *yamlDecoder) mapping(n *yaml.Node) (order.MapSlice, error) {
	out := order.MapSlice{}
	for i := 0; i+1 < len(n.Content); i += 2 {
		keyNode, valNode := n.Content[i], n.Content[i+1]
		if keyNode.Kind == yaml.ScalarNode && keyNode.Tag == "!!merge" {
			merged, err := d.mergeValue(valNode)
			if err != nil {
				return nil, err
			}
			for _, item := range merged {
				out = out.Delete(item.Key)
				out = append(out, item)
			}
			continue
		}
		key, err := d.node(keyNode)
		if err != nil {
			return nil, err
		}
		val, err := d.node(valNode)
		if err != nil {
			return nil, err
		}
		out = append(out, order.MapItem{Key: KeyString(key, d.keepSpecial), Val: val})
	}
	return out, nil
}

func (d *yamlDecoder) mergeValue(n *yaml.Node) (order.MapSlice, error) {
	target := n
	for target.Kind == yaml.AliasNode {
		target = target.Alias
	}
	if target.Kind != yaml.MappingNode {
		return nil, errors.New("map merge requires map or sequence of maps as the value")
	}
	v, err := d.node(n)
	if err != nil {
		return nil, err
	}
	m, ok := v.(order.MapSlice)
	if !ok {
