func specialStrings(v interface{}) interface{} {
	switch t := v.(type) {
	case order.MapSlice:
		for i := range t {
			t[i].Key = specialStrings(t[i].Key)
			t[i].Val = specialStrings(t[i].Val)
		}
		return t
	case []interface{}:
		for i := range t {
			t[i] = specialStrings(t[i])
		}
		return t
	case string:
		if f, ok := specialFloat(t); ok {
			return f
		}
	}
	return v
}

func specialFloat(s string) (float64, bool) {
	switch s {
	case "Infinity":
		return math.Inf(1), true
	case "-Infinity":
		return math.Inf(-1), true
	case "NaN":
		return math.NaN(), true
	}
	return 0, false
}

// restoreInfinities converts the largest finite floats back to infinities.
func restoreInfinities(v interface{}) interface{} {
	switch t := v.(type) {
	case order.MapSlice:
		for i := range t {
			t[i].Key = restoreInfinities(t[i].Key)
			t[i].Val = restoreInfinities(t[i].Val)
		}
		return t
	case []interface{}:
		for i := range t {
			t[i] = restoreInfinities(t[i])
		}
		return t
	case float64:
		switch t {
		case math.MaxFloat64:
			return math.Inf(1)
		case -math.MaxFloat64:
			return math.Inf(-1)
		}
	}
	return v
}

// Encode writes v as a YAML document.
func (y YAML) Encode(w io.Writer, v interface{}) error {
	node, err := y.toNode(v)
	if err != nil {
		return err
	}
	enc := yaml.NewEncoder(w)
	enc.SetIndent(2)
	if err := enc.Encode(node); err != nil {
		return err
	}
	return enc.Close()
}

// key prepares a map key for YAML output.
func (y YAML) key(k interface{}) (interface{}, error) {
	s := KeyString(k, y.KeepSpecialFloats)
