		v, err := JSON{KeepSpecialFloats: y.KeepSpecialFloats}.Decode(strings.NewReader(s))
		if err != nil {
			return s, nil
		}
		if y.KeepSpecialFloats && y.RestoreInfinities {
			v = restoreInfinities(v)
		}
		if v == nil {
			return nil, &reflect.ValueError{Method: "reflect.Value.Set", Kind: reflect.Invalid}
		}
		return v, nil
	}
	if !y.KeepSpecialFloats {
		if f, ok := specialFloat(s); ok {
			return f, nil
		}
	}
	return s, nil
}

func (y YAML) toNode(v interface{}) (*yaml.Node, error) {
	switch t := v.(type) {
	case order.MapSlice:
		n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, item := range t {
			key, err := y.key(item.Key)
			if err != nil {
				return nil, err
			}
			kn, err := y.toNode(key)
			if err != nil {
				return nil, err
			}
			vn, err := y.toNode(item.Val)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, kn, vn)
		}
		return n, nil
	case []interface{}:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, e := range t {
			en, err := y.toNode(e)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, en)
		}
		return n, nil
	case float64:
		return floatNode(t), nil
	case nil:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
	case time.Time:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!timestamp", Value: t.Format(time.RFC3339Nano)}, nil
	}
	n := &yaml.Node{}
	if err := n.Encode(v); err != nil {
		return nil, err
	}
	return n, nil
}

// floatNode formats a float so that it round-trips as a float: whole numbers
// get a trailing ".0" and special values use the YAML spellings.
func floatNode(f float64) *yaml.Node {
	var s string
	switch {
	case math.IsInf(f, 1):
		s = ".inf"
	case math.IsInf(f, -1):
		s = "-.inf"
	case math.IsNaN(f):
		s = ".nan"
	default:
		s = strconv.FormatFloat(f, 'g', -1, 64)
		if strings.Trim(s, "0123456789") == "" {
			s += ".0"
		}
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Value: s}
}
