	ILLEGAL: "ILLEGAL",
	EOF:     "EOF",
	COMMENT: "COMMENT",
	IDENT:   "IDENT",
	NUMBER:  "NUMBER",
	FLOAT:   "FLOAT",
	BOOL:    "BOOL",
	STRING:  "STRING",
	HEREDOC: "HEREDOC",
	LBRACK:  "LBRACK",
	LBRACE:  "LBRACE",
	COMMA:   "COMMA",
	PERIOD:  "PERIOD",
	RBRACK:  "RBRACK",
	RBRACE:  "RBRACE",
	ASSIGN:  "ASSIGN",
	ADD:     "ADD",
	SUB:     "SUB",
}

func (t TokenType) String() string {
	if int(t) < len(tokenNames) {
		return tokenNames[t]
	}
	return "TokenType(" + strconv.Itoa(int(t)) + ")"
}

// Token is a lexical token together with its position and source text.
type Token struct {
	Type TokenType
	Pos  Pos
	Text string
	// JSON marks string tokens that came from a JSON document and must be
	// unquoted with JSON rules.
	JSON bool
}

func (t Token) String() string {
	return fmt.Sprintf("%s %s %s", t.Pos.String(), t.Type.String(), t.Text)
}

// Value interprets the token text as a Go value. It panics when the text is
// malformed, mirroring the behaviour callers rely on to surface such errors.
func (t Token) Value() interface{} {
	switch t.Type {
	case BOOL:
		if t.Text == "true" {
			return true
		} else if t.Text == "false" {
			return false
		}
		panic("unknown bool value: " + t.Text)
	case FLOAT:
		v, err := strconv.ParseFloat(t.Text, 64)
		if err != nil {
			panic(err)
		}
		return v
	case NUMBER:
		v, err := strconv.ParseInt(t.Text, 0, 64)
		if err != nil {
			panic(err)
		}
		return v
	case IDENT:
		return t.Text
	case HEREDOC:
		return unindentHeredoc(t.Text)
	case STRING:
		f := Unquote
		if t.JSON {
			f = strconv.Unquote
		}
		if t.Text == "" {
			return ""
		}
		v, err := f(t.Text)
		if err != nil {
			panic(fmt.Sprintf("unquote %s err: %s", t.Text, err))
		}
		return v
	default:
		panic(fmt.Sprintf("unimplemented Value for type: %s", t.Type))
	}
}

// unindentHeredoc returns the body of a heredoc token, removing the common
// indentation when the marker was written as "<<-".
func unindentHeredoc(heredoc string) string {
	idx := strings.IndexByte(heredoc, '\n')
	if idx == -1 {
		panic("heredoc doesn't contain newline")
	}
	unindent := heredoc[2] == '-'
	if !unindent {
		return heredoc[idx+1 : len(heredoc)-idx+1]
	}
	lines := strings.Split(heredoc[idx+1:len(heredoc)-idx+2], "\n")
	whitespacePrefix := lines[len(lines)-1]
	isIndented := true
	for _, v := range lines {
		if strings.HasPrefix(v, whitespacePrefix) {
			continue
		}
		isIndented = false
		break
	}
	if !isIndented {
		return strings.TrimRight(heredoc[idx+1:len(heredoc)-idx+1], " \t")
	}
	unindentedLines := make([]string, len(lines))
	for k, v := range lines {
		if k == len(lines)-1 {
			unindentedLines[k] = ""
			break
		}
		unindentedLines[k] = strings.TrimPrefix(v, whitespacePrefix)
	}
	return strings.Join(unindentedLines, "\n")
}

func equalFold(a, b string) bool { return strings.EqualFold(a, b) }

func isLetter(ch rune) bool {
	return 'a' <= ch && ch <= 'z' || 'A' <= ch && ch <= 'Z' || ch == '_' || ch >= 0x80 && unicode.IsLetter(ch)
}

func isDigit(ch rune) bool {
	return '0' <= ch && ch <= '9' || ch >= 0x80 && unicode.IsDigit(ch)
}

func isDecimal(ch rune) bool { return '0' <= ch && ch <= '9' }

func isHexadecimal(ch rune) bool {
	return '0' <= ch && ch <= '9' || 'a' <= ch && ch <= 'f' || 'A' <= ch && ch <= 'F'
}

func isWhitespace(ch rune) bool {
	return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r'
}

func digitVal(ch rune) int {
	switch {
	case '0' <= ch && ch <= '9':
		return int(ch - '0')
	case 'a' <= ch && ch <= 'f':
		return int(ch - 'a' + 10)
	case 'A' <= ch && ch <= 'F':
		return int(ch - 'A' + 10)
	}
	return 16
}
