	s.ErrorCount++
	pos := s.tokPos
	pos.Offset = s.srcPos.Offset - s.lastCharLen
	pos.Line = s.srcPos.Line
	pos.Column = s.srcPos.Column
	if s.Error != nil {
		s.Error(pos, msg)
		return
	}
	fmt.Fprintf(os.Stderr, "%s: %s\n", pos, msg)
}
