type jsonToken struct {
	Type jsonTokenType
	Pos  Pos
	Text string
}

func (t jsonToken) String() string {
	return fmt.Sprintf("%s %s %s", t.Pos.String(), t.Type.String(), t.Text)
}

// HCLToken converts a literal JSON token into the equivalent HCL token.
// Positions are intentionally dropped, matching the behaviour the printer
// depends on for JSON derived trees.
func (t jsonToken) HCLToken() Token {
	switch t.Type {
	case jsonBOOL:
		return Token{Type: BOOL, Text: t.Text}
	case jsonFLOAT:
		return Token{Type: FLOAT, Text: t.Text}
	case jsonNULL:
		return Token{Type: STRING, Text: ""}
	case jsonNUMBER:
		return Token{Type: NUMBER, Text: t.Text}
	case jsonSTRING:
		return Token{Type: STRING, Text: t.Text, JSON: true}
	default:
		panic(fmt.Sprintf("unimplemented HCLToken for type: %s", t.Type))
	}
}

// jsonScanner tokenizes JSON source text.
type jsonScanner struct {
	buf *bytes.Buffer
	src []byte

	srcPos      Pos
	prevPos     Pos
	lastCharLen int
	lastLineLen int

	tokStart int
	tokEnd   int
	tokPos   Pos

	Error      func(pos Pos, msg string)
	ErrorCount int
}

func newJSONScanner(src []byte) *jsonScanner {
	s := &jsonScanner{buf: bytes.NewBuffer(src), src: src}
	s.srcPos.Line = 1
	return s
}

func (s *jsonScanner) next() rune {
	ch, size, err := s.buf.ReadRune()
	if err != nil {
		s.srcPos.Column++
		s.srcPos.Offset += size
		s.lastCharLen = size
		return eof
	}
	s.prevPos = s.srcPos
	s.srcPos.Column++
	s.lastCharLen = size
	s.srcPos.Offset += size
	if ch == utf8.RuneError && size == 1 {
		s.err("illegal UTF-8 encoding")
		return ch
	}
	if ch == '\n' {
		s.srcPos.Line++
		s.lastLineLen = s.srcPos.Column
		s.srcPos.Column = 0
	}
	return ch
}

func (s *jsonScanner) unread() {
	if err := s.buf.UnreadRune(); err != nil {
		panic(err)
	}
	s.srcPos = s.prevPos
}

func (s *jsonScanner) peek() rune {
	peek, _, err := s.buf.ReadRune()
	if err != nil {
		return eof
	}
	s.buf.UnreadRune()
	return peek
}

func (s *jsonScanner) Scan() jsonToken {
	ch := s.next()
	for isWhitespace(ch) {
		ch = s.next()
	}

	var tok jsonTokenType

	s.tokStart = s.srcPos.Offset - s.lastCharLen
	s.tokPos.Offset = s.srcPos.Offset - s.lastCharLen
	if s.srcPos.Column > 0 {
		s.tokPos.Line = s.srcPos.Line
		s.tokPos.Column = s.srcPos.Column
	} else {
		s.tokPos.Line = s.srcPos.Line - 1
		s.tokPos.Column = s.lastLineLen
	}

	switch {
	case isLetter(ch):
		lit := s.scanIdentifier()
		if lit == "true" || lit == "false" {
			tok = jsonBOOL
		} else if lit == "null" {
			tok = jsonNULL
		} else {
			s.err("illegal char")
		}
	case isDecimal(ch):
		tok = s.scanNumber(ch)
	default:
		switch ch {
		case eof:
			tok = jsonEOF
		case '"':
			tok = jsonSTRING
			s.scanString()
		case '.':
			tok = jsonPERIOD
			ch = s.peek()
			if isDecimal(ch) {
				tok = jsonFLOAT
				ch = s.scanMantissa(ch)
				ch = s.scanFraction(ch)
			}
		case '[':
			tok = jsonLBRACK
		case ']':
			tok = jsonRBRACK
		case '{':
			tok = jsonLBRACE
		case '}':
			tok = jsonRBRACE
		case ',':
			tok = jsonCOMMA
		case ':':
			tok = jsonCOLON
		case '-':
			if isDecimal(s.peek()) {
				ch := s.next()
				tok = s.scanNumber(ch)
			} else {
				s.err("illegal char")
			}
		default:
			s.err("illegal char: " + string(ch))
		}
	}

	s.tokEnd = s.srcPos.Offset

	var tokenText string
	if s.tokStart >= 0 {
		tokenText = string(s.src[s.tokStart:s.tokEnd])
	}
	s.tokStart = s.tokEnd

	return jsonToken{Type: tok, Pos: s.tokPos, Text: tokenText}
}

func (s *jsonScanner) scanNumber(ch rune) jsonTokenType {
	zero := ch == '0'
	pos := s.srcPos

	s.scanMantissa(ch)
	ch = s.next()
	if ch == 'e' || ch == 'E' {
		ch = s.scanExponent(ch)
		return jsonFLOAT
	}

	if ch == '.' {
		ch = s.scanFraction(ch)
		if ch == 'e' || ch == 'E' {
			ch = s.next()
			ch = s.scanExponent(ch)
		}
		return jsonFLOAT
	}

	if ch != eof {
		s.unread()
	}

	if zero && pos != s.srcPos {
		s.err("numbers cannot start with 0")
	}

	return jsonNUMBER
}

func (s *jsonScanner) scanMantissa(ch rune) rune {
	scanned := false
	for isDecimal(ch) {
		ch = s.next()
		scanned = true
	}
	if scanned && ch != eof {
		s.unread()
	}
	return ch
}

func (s *jsonScanner) scanFraction(ch rune) rune {
	if ch == '.' {
		ch = s.peek()
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *jsonScanner) scanExponent(ch rune) rune {
	if ch == 'e' || ch == 'E' {
		ch = s.next()
		if ch == '-' || ch == '+' {
			ch = s.next()
		}
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *jsonScanner) scanString() {
	for {
		ch := s.next()
		if ch == '\n' || ch < 0 || ch == eof {
			s.err("literal not terminated")
			return
		}
		if ch == '"' {
			break
		}
		if ch == '\\' {
			s.scanEscape()
		}
	}
}

func (s *jsonScanner) scanEscape() rune {
	ch := s.next()
	switch ch {
	case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', '"':
	case '0', '1', '2', '3', '4', '5', '6', '7':
		ch = s.scanDigits(ch, 8, 3)
	case 'x':
		ch = s.scanDigits(s.next(), 16, 2)
	case 'u':
		ch = s.scanDigits(s.next(), 16, 4)
	case 'U':
		ch = s.scanDigits(s.next(), 16, 8)
	default:
		s.err("illegal char escape")
	}
	return ch
}

func (s *jsonScanner) scanDigits(ch rune, base, n int) rune {
	for n > 0 && digitVal(ch) < base {
		ch = s.next()
		n--
	}
	if n > 0 {
		s.err("illegal char escape")
	}
	s.unread()
	return ch
}

func (s *jsonScanner) scanIdentifier() string {
	offs := s.srcPos.Offset - s.lastCharLen
	ch := s.next()
	for isLetter(ch) || isDigit(ch) || ch == '-' {
		ch = s.next()
	}
	if ch != eof {
		s.unread()
	}
	return string(s.src[offs:s.srcPos.Offset])
}

func (s *jsonScanner) err(msg string) {
	s.ErrorCount++
	pos := s.tokPos
	pos.Offset = s.srcPos.Offset - s.lastCharLen
	pos.Line = s.srcPos.Line
	pos.Column = s.srcPos.Column
	if s.Error != nil {
		s.Error(pos, msg)
		return
	}
	fmt.Fprintf(os.Stderr, "%s: %s\n", pos, msg)
}

// jsonParser builds an HCL syntax tree from JSON source.
type jsonParser struct {
	sc  *jsonScanner
	tok jsonToken
	n   int
}

// ParseJSON parses a JSON document into an HCL syntax tree.
func ParseJSON(src []byte) (*File, error) {
	p := &jsonParser{sc: newJSONScanner(src)}
	return p.parse()
}

func (p *jsonParser) parse() (*File, error) {
	f := &File{}
	var err, scerr error
	p.sc.Error = func(pos Pos, msg string) {
		scerr = fmt.Errorf("%s: %s", pos, msg)
	}

	object, err := p.object()
	if scerr != nil {
		return nil, scerr
	}
	if err != nil {
		return nil, err
	}

	f.Node = object.List
	flattenObjects(f.Node)
	return f, nil
}

func (p *jsonParser) objectList() (*ObjectList, error) {
	node := &ObjectList{}
	for {
		n, err := p.objectItem()
		if err == errEofToken {
			break
		}
		if err != nil {
			return node, err
		}
		node.Add(n)

		if tok := p.scan(); tok.Type != jsonCOMMA {
			break
		}
	}
	return node, nil
}

func (p *jsonParser) objectItem() (*ObjectItem, error) {
	keys, err := p.objectKey()
	if err != nil {
		return nil, err
	}

	o := &ObjectItem{Keys: keys}

	switch p.tok.Type {
	case jsonCOLON:
		pos := p.tok.Pos
		o.Assign = Pos{Filename: pos.Filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column}
		o.Val, err = p.objectValue()
		if err != nil {
			return nil, err
		}
	}
	return o, nil
}

func (p *jsonParser) objectKey() ([]*ObjectKey, error) {
	keyCount := 0
	keys := make([]*ObjectKey, 0)

	for {
		tok := p.scan()
		switch tok.Type {
		case jsonEOF:
			return nil, errEofToken
		case jsonSTRING:
			keyCount++
			keys = append(keys, &ObjectKey{Token: p.tok.HCLToken()})
		case jsonCOLON:
			if keyCount == 0 {
				return nil, fmt.Errorf("expected: STRING got: %s", p.tok.Type)
			}
			return keys, nil
		case jsonILLEGAL:
			return nil, errors.New("illegal")
		default:
			return nil, fmt.Errorf("expected: STRING got: %s", p.tok.Type)
		}
	}
}

func (p *jsonParser) objectValue() (Node, error) {
	tok := p.scan()
	switch tok.Type {
	case jsonNUMBER, jsonFLOAT, jsonBOOL, jsonNULL, jsonSTRING:
		return p.literalType()
	case jsonLBRACE:
		return p.objectType()
	case jsonLBRACK:
		return p.listType()
	case jsonEOF:
		return nil, errEofToken
	}
	return nil, fmt.Errorf("Expected object value, got unknown token: %+v", tok)
}

func (p *jsonParser) object() (*ObjectType, error) {
	tok := p.scan()
	switch tok.Type {
	case jsonLBRACE:
		return p.objectType()
	case jsonEOF:
		return nil, errEofToken
	}
	return nil, fmt.Errorf("Expected object, got unknown token: %+v", tok)
}

func (p *jsonParser) objectType() (*ObjectType, error) {
	o := &ObjectType{}

	l, err := p.objectList()
	if err != nil && p.tok.Type != jsonRBRACE {
		return nil, err
	}

	o.List = l
	return o, nil
}

func (p *jsonParser) listType() (*ListType, error) {
	l := &ListType{}

	for {
		tok := p.scan()
		switch tok.Type {
		case jsonNUMBER, jsonFLOAT, jsonSTRING:
			node, err := p.literalType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
		case jsonCOMMA:
			continue
		case jsonLBRACE:
			node, err := p.objectType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
		case jsonBOOL:
			// booleans inside lists are not supported by the reference grammar
		case jsonLBRACK:
			// nested lists are flattened into the enclosing list
		case jsonRBRACK:
			return l, nil
		default:
			return nil, fmt.Errorf("unexpected token while parsing list: %s", tok.Type)
		}
	}
}

func (p *jsonParser) literalType() (*LiteralType, error) {
	return &LiteralType{Token: p.tok.HCLToken()}, nil
}

func (p *jsonParser) scan() jsonToken {
	if p.n != 0 {
		p.n = 0
		return p.tok
	}
	p.tok = p.sc.Scan()
	return p.tok
}

func (p *jsonParser) unscan() { p.n = 1 }

// flattenObjects rewrites the tree so that objects whose members are all
// objects, and lists whose members are all objects, become multiple items
// with compound keys, as native HCL would express them.
func flattenObjects(node Node) {
	Walk(node, func(n Node) (Node, bool) {
		list, ok := n.(*ObjectList)
		if !ok {
			return n, true
		}

		items := make([]*ObjectItem, 0, len(list.Items))
		frontier := make([]*ObjectItem, len(list.Items))
		copy(frontier, list.Items)
		for len(frontier) > 0 {
			n := len(frontier)
			item := frontier[n-1]
			frontier = frontier[:n-1]

			switch v := item.Val.(type) {
			case *ObjectType:
				items, frontier = flattenObjectType(v, item, items, frontier)
			case *ListType:
				items, frontier = flattenListType(v, item, items, frontier)
			default:
				items = append(items, item)
			}
		}

		for i := len(items)/2 - 1; i >= 0; i-- {
			opp := len(items) - 1 - i
			items[i], items[opp] = items[opp], items[i]
		}

		list.Items = items
		return n, true
	})
}

func flattenListType(ot *ListType, item *ObjectItem, items []*ObjectItem, frontier []*ObjectItem) ([]*ObjectItem, []*ObjectItem) {
	if len(ot.List) == 0 {
		items = append(items, item)
		return items, frontier
	}
	for _, subitem := range ot.List {
		if _, ok := subitem.(*ObjectType); !ok {
			items = append(items, item)
			return items, frontier
		}
	}
	for _, elem := range ot.List {
		frontier = append(frontier, &ObjectItem{
			Keys:        item.Keys,
			Assign:      item.Assign,
			Val:         elem,
			LeadComment: item.LeadComment,
			LineComment: item.LineComment,
		})
	}
	return items, frontier
}

func flattenObjectType(ot *ObjectType, item *ObjectItem, items []*ObjectItem, frontier []*ObjectItem) ([]*ObjectItem, []*ObjectItem) {
	if ot.List.Items == nil {
		items = append(items, item)
		return items, frontier
	}
	for _, subitem := range ot.List.Items {
		if _, ok := subitem.Val.(*ObjectType); !ok {
			items = append(items, item)
			return items, frontier
		}
	}
	for _, subitem := range ot.List.Items {
		keys := make([]*ObjectKey, len(item.Keys)+len(subitem.Keys))
		copy(keys, item.Keys)
		copy(keys[len(item.Keys):], subitem.Keys)

		frontier = append(frontier, &ObjectItem{
			Keys:        keys,
			Assign:      item.Assign,
			Val:         subitem.Val,
			LeadComment: item.LeadComment,
			LineComment: item.LineComment,
		})
	}
	return items, frontier
}
