			}

			if curPos.Line-1 == prevPos.Line {
				aligned = append(aligned, item)
				index++
				if curPos.Line+1 != nextPos.Line {
					break
				}
				continue
			}

			break
		}

		if !commented && index != 0 {
			buf.WriteByte(newline)
		}

		if len(aligned) >= 2 {
			p.prev = aligned[len(aligned)-1].Pos()
			buf.Write(p.indent(p.alignedItems(aligned)))
		} else {
			p.prev = o.List.Items[index].Pos()
			buf.Write(p.indent(p.objectItem(o.List.Items[index])))
			index++
		}

		buf.WriteByte(newline)
	}

	buf.WriteString("}")
	return buf.Bytes()
}

func (p *printer) alignedItems(items []*ObjectItem) []byte {
	var buf bytes.Buffer

	var longestLine int
	for _, item := range items {
		lineLen := 0
		for i, k := range item.Keys {
			lineLen += len(k.Token.Text)
			if i != len(item.Keys)-1 {
				lineLen++
			}
		}
		if lineLen > longestLine {
			longestLine = lineLen
		}
	}

	for i, item := range items {
		if item.LeadComment != nil {
			for _, comment := range item.LeadComment.List {
				buf.WriteString(comment.Text)
				buf.WriteByte(newline)
			}
		}

		curLen := 0
		for i, k := range item.Keys {
			buf.WriteString(k.Token.Text)
			curLen += len(k.Token.Text)
			if i != len(item.Keys)-1 {
				buf.WriteByte(blank)
				curLen++
			}
		}

		if item.Assign.IsValid() {
			for i := 0; i < longestLine-curLen+1; i++ {
				buf.WriteByte(blank)
			}
			buf.WriteString("=")
			buf.WriteByte(blank)
		} else {
			buf.WriteByte(blank)
		}

		val := p.output(item.Val)
		buf.Write(val)

		if item.LineComment != nil {
			for _, comment := range item.LineComment.List {
				buf.WriteByte(blank)
				buf.WriteString(comment.Text)
			}
		}

		if i != len(items)-1 {
			buf.WriteByte(newline)
		}
	}

	return buf.Bytes()
}

func (p *printer) list(l *ListType) []byte {
	if p.isSingleLineList(l) {
		return p.singleLineList(l)
	}

	var buf bytes.Buffer
	buf.WriteString("[")
	buf.WriteByte(newline)

	var longestLine int
	for _, item := range l.List {
		if lit, ok := item.(*LiteralType); ok {
			lineLen := len(lit.Token.Text)
			if lineLen > longestLine {
				longestLine = lineLen
			}
		}
	}

	haveEmptyLine := false
	for i, item := range l.List {
		leadComment := false
		if lit, ok := item.(*LiteralType); ok && lit.LeadComment != nil {
			leadComment = true
			if !haveEmptyLine && i != 0 {
				buf.WriteByte(newline)
			}
			for _, comment := range lit.LeadComment.List {
				buf.Write(p.indent([]byte(comment.Text)))
				buf.WriteByte(newline)
			}
		}

		val := p.output(item)
		curLen := len(val)
		buf.Write(p.indent(val))

		comma := []byte{','}
		if lit, ok := item.(*LiteralType); ok && lit.Token.Type == HEREDOC {
			buf.WriteByte(newline)
			comma = p.indent(comma)
		}

		buf.Write(comma)

		if lit, ok := item.(*LiteralType); ok && lit.LineComment != nil {
			buf.WriteByte(blank)
			for i := 0; i < longestLine-curLen; i++ {
				buf.WriteByte(blank)
			}
			for _, comment := range lit.LineComment.List {
				buf.WriteString(comment.Text)
			}
		}

		buf.WriteByte(newline)

		haveEmptyLine = leadComment && i != len(l.List)-1
		if haveEmptyLine {
			buf.WriteByte(newline)
		}
	}

	buf.WriteString("]")
	return buf.Bytes()
}

func (p *printer) isSingleLineList(l *ListType) bool {
	for _, item := range l.List {
		if _, ok := item.(*LiteralType); !ok {
			return false
		}
		if item.Pos().Line != l.Lbrack.Line {
			return false
		}
		lit, ok := item.(*LiteralType)
		if ok && lit.Token.Type == HEREDOC && len(l.List) != 1 {
			return false
		}
		if ok && lit.LineComment != nil {
			return false
		}
	}
	return true
}

func (p *printer) singleLineList(l *ListType) []byte {
	buf := &bytes.Buffer{}

	buf.WriteString("[")
	for i, item := range l.List {
		if i != 0 {
			buf.WriteString(", ")
		}
		buf.Write(p.output(item))
		if lit, ok := item.(*LiteralType); ok && lit.Token.Type == HEREDOC {
			buf.WriteByte(newline)
		}
	}
	buf.WriteString("]")
	return buf.Bytes()
}

func (p *printer) indent(buf []byte) []byte {
	var prefix []byte
	if p.cfg.SpacesWidth != 0 {
		for i := 0; i < p.cfg.SpacesWidth; i++ {
			prefix = append(prefix, blank)
		}
	} else {
		prefix = []byte{tab}
	}

	var res []byte
	bol := true
	for _, c := range buf {
		if bol && c != '\n' {
			res = append(res, prefix...)
		}
		res = append(res, c)
		bol = c == '\n'
	}
	return res
}

func (p *printer) unindent(buf []byte) []byte {
	var res []byte
	for i := 0; i < len(buf); i++ {
		skip := len(buf)-i <= len(unindentMarker)
		if !skip {
			skip = !bytes.Equal(unindentMarker, buf[i:i+len(unindentMarker)])
		}
		if skip {
			res = append(res, buf[i])
			continue
		}
		for j := len(res) - 1; j >= 0; j-- {
			if res[j] == '\n' {
				break
			}
			res = res[:j]
		}
		i += len(unindentMarker) - 1
	}
	return res
}

func (p *printer) heredocIndent(buf []byte) []byte {
	var res []byte
	bol := false
	for _, c := range buf {
		if bol && c != '\n' {
			res = append(res, unindentMarker...)
		}
		res = append(res, c)
		bol = c == '\n'
	}
	return res
}

func (p *printer) isSingleLineObject(val *ObjectItem) bool {
	ot, ok := val.Val.(*ObjectType)
	if !ok {
		return true
	}
	return ot.Lbrace.Line == ot.Rbrace.Line
}

func lines(txt string) int {
	endline := 1
	for i := 0; i < len(txt); i++ {
		if txt[i] == '\n' {
			endline++
		}
	}
	return endline
}

