package hcl

import (
	"bytes"
	"fmt"
	"io"
	"sort"
	"strings"
)

const (
	blank    = byte(' ')
	newline  = byte('\n')
	tab      = byte('\t')
	infinity = 1 << 30
)

var unindentMarker = []byte("\uE123")

// PrintConfig controls the printer's output.
type PrintConfig struct {
	SpacesWidth int
}

// DefaultPrintConfig uses two space indentation.
var DefaultPrintConfig = &PrintConfig{SpacesWidth: 2}

type printer struct {
	cfg                PrintConfig
	prev               Pos
	comments           []*CommentGroup
	standaloneComments []*CommentGroup
}

// Fprint pretty prints node to output.
func Fprint(output io.Writer, node Node) error {
	return DefaultPrintConfig.Fprint(output, node)
}

// Fprint pretty prints node to output using the configuration.
func (c *PrintConfig) Fprint(output io.Writer, node Node) error {
	p := &printer{
		cfg:                *c,
		comments:           make([]*CommentGroup, 0),
		standaloneComments: make([]*CommentGroup, 0),
	}
	p.collectComments(node)
	_, err := output.Write(p.unindent(p.output(node)))
	return err
}

func (p *printer) collectComments(node Node) {
	f, ok := node.(*File)
	if !ok {
		return
	}
	p.comments = f.Comments

	standaloneComments := make(map[Pos]*CommentGroup, 0)
	for _, c := range f.Comments {
		for _, comment := range c.List {
			standaloneComments[comment.Pos()] = c
		}
	}

	Walk(node, func(nn Node) (Node, bool) {
		switch t := nn.(type) {
		case *LiteralType:
			if t.LeadComment != nil {
				for _, comment := range t.LeadComment.List {
					delete(standaloneComments, comment.Pos())
				}
			}
			if t.LineComment != nil {
				for _, comment := range t.LineComment.List {
					delete(standaloneComments, comment.Pos())
				}
			}
		case *ObjectItem:
			if t.LeadComment != nil {
				for _, comment := range t.LeadComment.List {
					delete(standaloneComments, comment.Pos())
				}
			}
			if t.LineComment != nil {
				for _, comment := range t.LineComment.List {
					delete(standaloneComments, comment.Pos())
				}
			}
		}
		return nn, true
	})

	for _, c := range standaloneComments {
		p.standaloneComments = append(p.standaloneComments, c)
	}
	sort.Sort(byPosition(p.standaloneComments))
}

type byPosition []*CommentGroup

func (b byPosition) Len() int           { return len(b) }
func (b byPosition) Swap(i, j int)      { b[i], b[j] = b[j], b[i] }
func (b byPosition) Less(i, j int) bool { return b[i].Pos().Before(b[j].Pos()) }

func (p *printer) output(n interface{}) []byte {
	var buf bytes.Buffer

	switch t := n.(type) {
	case *File:
		return p.output(t.Node)
	case *ObjectList:
		var index int
		for {
			var nextItem Pos
			if index != len(t.Items) {
				nextItem = t.Items[index].Pos()
			} else {
				nextItem = Pos{Offset: infinity, Line: infinity}
			}

			for _, c := range p.standaloneComments {
				printed := false
				newlinePrinted := false
				for _, comment := range c.List {
					if comment.Pos().After(p.prev) {
						if !newlinePrinted {
							newlinePrinted = true
							buf.WriteByte(newline)
						}
						if index > 0 {
							buf.WriteByte(newline)
						}
						if comment.Pos().Before(nextItem) {
							buf.WriteString(comment.Text)
							buf.WriteByte(newline)
							printed = true
						}
					}
				}
				if printed && index != len(t.Items) {
					buf.WriteByte(newline)
				}
			}

			if index == len(t.Items) {
				break
			}

			buf.Write(p.output(t.Items[index]))
			if index != len(t.Items)-1 {
				buf.WriteByte(newline)

				current := t.Items[index]
				next := t.Items[index+1]
				if next.Pos().Line != t.Items[index].Pos().Line+1 ||
					!p.isSingleLineObject(next) ||
					!p.isSingleLineObject(current) {
					buf.WriteByte(newline)
				}
			}
			index++
		}
	case *ObjectKey:
		buf.WriteString(t.Token.Text)
	case *ObjectItem:
		p.prev = t.Pos()
		buf.Write(p.objectItem(t))
	case *LiteralType:
		buf.Write(p.literalType(t))
	case *ListType:
		buf.Write(p.list(t))
	case *ObjectType:
		buf.Write(p.objectType(t))
	default:
		fmt.Printf(" unknown type: %T\n", n)
	}

	return buf.Bytes()
}

func (p *printer) literalType(lit *LiteralType) []byte {
	result := []byte(lit.Token.Text)
	switch lit.Token.Type {
	case HEREDOC:
		if len(result) > 0 && result[len(result)-1] == '\n' {
			result = result[:len(result)-1]
		}
		result = p.heredocIndent(result)
	case STRING:
		if bytes.IndexRune(result, '\n') >= 0 {
			result = p.heredocIndent(result)
		}
	}
	return result
}

func (p *printer) objectItem(o *ObjectItem) []byte {
	var buf bytes.Buffer

	if o.LeadComment != nil {
		for _, comment := range o.LeadComment.List {
			buf.WriteString(comment.Text)
			buf.WriteByte(newline)
		}
	}

	if o.LineComment != nil && o.Val.Pos().Line != o.Keys[0].Pos().Line {
		for _, comment := range o.LineComment.List {
			buf.WriteString(comment.Text)
			buf.WriteByte(newline)
		}
	}

	for i, k := range o.Keys {
		buf.WriteString(k.Token.Text)
		buf.WriteByte(blank)

		if o.Assign.IsValid() && i == len(o.Keys)-1 && len(o.Keys) == 1 {
			buf.WriteString("=")
			buf.WriteByte(blank)
		}
	}

	buf.Write(p.output(o.Val))

	if o.LineComment != nil && o.Val.Pos().Line == o.Keys[0].Pos().Line {
		buf.WriteByte(blank)
		for _, comment := range o.LineComment.List {
			buf.WriteString(comment.Text)
		}
	}

	return buf.Bytes()
}

func (p *printer) objectType(o *ObjectType) []byte {
	var buf bytes.Buffer
	buf.WriteString("{")

	var index int
	var nextItem Pos
	var commented, newlinePrinted bool
	for {
		if index != len(o.List.Items) {
			nextItem = o.List.Items[index].Pos()
		} else {
			nextItem = o.Rbrace
		}

		for _, c := range p.standaloneComments {
			printed := false
			var lastCommentPos Pos
			for _, comment := range c.List {
				if comment.Pos().After(p.prev) {
					if !newlinePrinted {
						newlinePrinted = true
						buf.WriteByte(newline)
					}
					if index > 0 {
						commented = true
						buf.WriteByte(newline)
					}
					lastCommentPos = comment.Pos()
					buf.Write(p.indent(p.heredocIndent([]byte(comment.Text))))
					printed = true
				}
			}
			if printed {
				buf.WriteByte(newline)
				if nextItem != o.Rbrace && nextItem.Line != lastCommentPos.Line+1 {
					buf.WriteByte(newline)
				}
			}
		}

		if index == len(o.List.Items) {
			p.prev = o.Rbrace
			break
		}

		if !newlinePrinted {
			buf.WriteByte(newline)
			newlinePrinted = true
		}

		var aligned []*ObjectItem
		for _, item := range o.List.Items[index:] {
			if len(o.List.Items) == 1 {
				break
			}

			cur := lines(string(p.objectItem(item)))
			if cur > 2 {
				break
			}

			curPos := item.Pos()

			nextPos := Pos{}
			if index != len(o.List.Items)-1 {
				nextPos = o.List.Items[index+1].Pos()
			}

			prevPos := Pos{}
			if index != 0 {
				prevPos = o.List.Items[index-1].Pos()
			}

			if curPos.Line+1 == nextPos.Line {
				aligned = append(aligned, item)
				index++
				continue
			}

			if curPos.Line-1 == prevPos.Line {
				aligned = append(aligned, item)
				index++
				if curPos.Line+1 != nextPos.Line {
					break
				}
				continue
			}

			break
		}

		if !commented && index != 0 {
			buf.WriteByte(newline)
		}

		if len(aligned) >= 2 {
			p.prev = aligned[len(aligned)-1].Pos()
			buf.Write(p.indent(p.alignedItems(aligned)))
		} else {
			p.prev = o.List.Items[index].Pos()
			buf.Write(p.indent(p.objectItem(o.List.Items[index])))
			index++
		}

		buf.WriteByte(newline)
	}

	buf.WriteString("}")
	return buf.Bytes()
}

