	"yj/hcl"
	"yj/order"
)

// HCL converts between the generic ordered tree and HCL documents.
type HCL struct {
	// KeepSpecialFloats disables conversion of the strings "Infinity",
	// "-Infinity" and "NaN" into floats while decoding.
	KeepSpecialFloats bool
}

// Decode parses the HCL (or JSON) document in r.
func (h HCL) Decode(r io.Reader) (v interface{}, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	defer func() {
		if rec := recover(); rec != nil {
			if e, ok := rec.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("unexpected failure: %v", rec)
			}
			v = nil
		}
	}()
	file, err := hcl.Parse(data)
	if err != nil {
		return nil, err
	}
	list, ok := file.Node.(*hcl.ObjectList)
	if !ok {
		return nil, fmt.Errorf("unexpected root node: %T", file.Node)
	}
	v, err = decodeObjectList(list)
	if err != nil {
		return nil, err
	}
	if !h.KeepSpecialFloats {
		v = specialStrings(v)
	}
	return v, nil
}

// decodeObjectList turns an object list into an ordered map. Items sharing a
// key accumulate into a list, and items with several keys are grouped into a
// nested object, mirroring how blocks are usually interpreted.
func decodeObjectList(list *hcl.ObjectList) (order.MapSlice, error) {
	out := order.MapSlice{}
	done := map[string]bool{}
	for _, item := range list.Items {
		if len(item.Keys) == 0 {
			return nil, fmt.Errorf("empty key at line %d", item.Pos().Line)
		}
		key := item.Keys[0].Token.Value().(string)
		if len(item.Keys) == 1 {
			val, err := decodeNode(item.Val)
			if err != nil {
				return nil, err
			}
			switch t := val.(type) {
			case []interface{}:
				for _, elem := range t {
					if out, err = appendValue(out, key, elem); err != nil {
						return nil, err
					}
				}
			case order.MapSlice:
				if out, err = appendValue(out, key, t); err != nil {
					return nil, err
				}
			default:
				if out, err = setValue(out, key, val); err != nil {
					return nil, err
				}
			}
			continue
		}
		if done[key] {
			continue
		}
		done[key] = true
		sub, err := decodeObjectList(list.Filter(key))
		if err != nil {
			return nil, err
		}
		if out, err = appendValue(out, key, sub); err != nil {
			return nil, err
		}
	}
	return out, nil
}

func decodeNode(n hcl.Node) (interface{}, error) {
	switch t := n.(type) {
	case *hcl.LiteralType:
		return t.Token.Value(), nil
	case *hcl.ListType:
		out := make([]interface{}, 0, len(t.List))
		for _, elem := range t.List {
			v, err := decodeNode(elem)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case *hcl.ObjectType:
		return decodeObjectList(t.List)
	case *hcl.ObjectList:
		return decodeObjectList(t)
	}
	return nil, fmt.Errorf("unexpected node: %T", n)
}

func appendValue(m order.MapSlice, key string, val interface{}) (order.MapSlice, error) {
	i := m.Index(key)
	if i < 0 {
		return append(m, order.MapItem{Key: key, Val: []interface{}{val}}), nil
	}
	list, ok := m[i].Val.([]interface{})
	if !ok {
		return nil, fmt.Errorf("cannot append '%#v' to '%#v", val, m[i].Val)
	}
	m[i].Val = append(list, val)
	return m, nil
}

func setValue(m order.MapSlice, key string, val interface{}) (order.MapSlice, error) {
	i := m.Index(key)
	if i < 0 {
		return append(m, order.MapItem{Key: key, Val: val}), nil
	}
	if _, ok := m[i].Val.([]interface{}); ok {
		return nil, fmt.Errorf("cannot set '%#v' over '%#v", val, m[i].Val)
	}
	m[i].Val = val
	return m, nil
}

// Encode writes v as HCL. The tree is first serialized as JSON and then
// parsed with the HCL JSON front end so that the printer produces the same
// layout the reference implementation does.
func (h HCL) Encode(w io.Writer, v interface{}) (err error) {
	var buf bytes.Buffer
	if err := (JSON{}).Encode(&buf, v); err != nil {
		return err
	}
	defer func() {
		if rec := recover(); rec != nil {
			if e, ok := rec.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("unexpected failure: %v", rec)
			}
		}
	}()
	file, err := hcl.ParseJSON(bytes.TrimRight(buf.Bytes(), "\n"))
	if err != nil {
		return err
	}
	return hcl.Fprint(w, file)
}
