// Package toml implements a TOML decoder and encoder tailored to the ordered
// document model used by yj.
package toml

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
	"time"
)

// Struct is an ordered collection of named fields, the TOML equivalent of a
// Go struct value. Field order is preserved in the output.
type Struct struct {
	Fields []Field
}

// Field is a single member of a Struct. Name is the fallback key used when the
// Tag does not provide one. Tag follows the familiar struct tag conventions:
// a key name optionally followed by comma separated options.
type Field struct {
	Name string
	Tag  string
	Val  interface{}
}

type tagOptions struct {
	skip      bool
	name      string
	omitempty bool
	omitzero  bool
}

func parseTag(tag string) tagOptions {
	if tag == "-" {
		return tagOptions{skip: true}
	}
	var opts tagOptions
	parts := strings.Split(tag, ",")
	opts.name = parts[0]
	for _, s := range parts[1:] {
		switch s {
		case "omitempty":
			opts.omitempty = true
		case "omitzero":
			opts.omitzero = true
		}
	}
	return opts
}

var (
	errNoKey           = errors.New("toml: top-level values must be Go maps or structs")
	errArrayNilElement = errors.New("toml: cannot encode array with nil element")
)

type tomlType int

const (
	typeNone tomlType = iota
	typeBool
