// TOML converts between the generic ordered tree and TOML documents.
type TOML struct {
	// KeepSpecialFloats disables conversion between the strings "Infinity",
	// "-Infinity", "NaN" and the matching float values while decoding.
	KeepSpecialFloats bool
	// Indent enables indentation of nested tables in the output.
	Indent bool
}

// Decode parses the TOML document in r.
func (t TOML) Decode(r io.Reader) (interface{}, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	return toml.Decode(string(data))
}

// Encode writes v as a TOML document.
func (t TOML) Encode(w io.Writer, v interface{}) error {
	enc := toml.NewEncoder(w)
	if t.Indent {
		enc.Indent = "  "
	}
	return enc.Encode(t.prepare(v))
}

// prepare converts the generic tree into the encoder's representation:
// ordered maps become structs whose fields are tagged with their keys, and
// nil list elements are dropped.
func (t TOML) prepare(v interface{}) interface{} {
	switch val := v.(type) {
	case order.MapSlice:
		st := &toml.Struct{Fields: make([]toml.Field, 0, len(val))}
		for i, item := range val {
			st.Fields = append(st.Fields, toml.Field{
				Name: fieldName(i),
				Tag:  KeyString(item.Key, t.KeepSpecialFloats),
				Val:  t.prepare(item.Val),
			})
		}
		return st
	case []interface{}:
		out := make([]interface{}, 0, len(val))
		for _, elem := range val {
			if elem == nil {
				continue
			}
			out = append(out, t.prepare(elem))
		}
		return out
	}
	return v
}

// fieldName generates an exported identifier for the i-th field: A..Z, then
// BA..BZ and so on.
func fieldName(i int) string {
	if i < 26 {
		return string(rune('A' + i))
	}
	return fieldName(i/26) + string(rune('A'+i%26))
}
