// ParseError describes a syntax or semantic error in a TOML document.
type ParseError struct {
	Message  string
	Position Position
	LastKey  string
}

func (pe ParseError) Error() string {
	if pe.LastKey == "" {
		return fmt.Sprintf("toml: line %d: %s", pe.Position.Line, pe.Message)
	}
	return fmt.Sprintf("toml: line %d (last key %q): %s", pe.Position.Line, pe.LastKey, pe.Message)
}

type (
	errLexControl       struct{ r rune }
	errLexEscape        struct{ r rune }
	errLexUTF8          struct{ b byte }
	errLexInlineTableNL struct{}
	errLexStringNL      struct{}
	errParseRange       struct {
		i    interface{}
		size string
	}
)

func (e errLexControl) Error() string {
	return fmt.Sprintf("TOML files cannot contain control characters: '0x%02x'", e.r)
}
func (e errLexEscape) Error() string        { return fmt.Sprintf(`invalid escape in string '\%c'`, e.r) }
func (e errLexUTF8) Error() string          { return fmt.Sprintf("invalid UTF-8 byte: 0x%02x", e.b) }
func (e errLexInlineTableNL) Error() string { return "newlines not allowed within inline tables" }
func (e errLexStringNL) Error() string      { return "strings cannot contain newlines" }
func (e errParseRange) Error() string       { return fmt.Sprintf("%v is out of range for %s", e.i, e.size) }

type tomlType int

const (
	tomlTypeNone tomlType = iota
	tomlTypeBool
	tomlTypeInteger
	tomlTypeFloat
	tomlTypeDatetime
	tomlTypeString
	tomlTypeArray
	tomlTypeHash
	tomlTypeArrayHash
)

// table is an insertion ordered mapping used while parsing.
type table struct {
	keys []string
	vals map[string]interface{}
}

func newTable() *table { return &table{vals: map[string]interface{}{}} }

func (t *table) set(key string, val interface{}) {
	if _, ok := t.vals[key]; !ok {
		t.keys = append(t.keys, key)
	}
	t.vals[key] = val
}

// tableArray is an array of tables created by [[...]] headers.
type tableArray struct {
	tables []*table
}

type parser struct {
	lx         *lexer
	context    Key
	currentKey string
	pos        Position

	keyInfo   map[string]tomlType
	mapping   *table
	implicits map[string]struct{}
}

// Decode parses data and returns the document as an ordered tree.
func Decode(data string) (interface{}, error) {
	p, err := parse(data)
	if err != nil {
		return nil, err
	}
	return convertTable(p.mapping), nil
}

func convertTable(t *table) order.MapSlice {
	out := make(order.MapSlice, 0, len(t.keys))
	for _, k := range t.keys {
		out = append(out, order.MapItem{Key: k, Val: convertValue(t.vals[k])})
	}
	return out
}

func convertValue(v interface{}) interface{} {
	switch t := v.(type) {
	case *table:
		return convertTable(t)
	case *tableArray:
		out := make([]interface{}, 0, len(t.tables))
		for _, tbl := range t.tables {
			out = append(out, convertTable(tbl))
		}
		return out
	case []interface{}:
		out := make([]interface{}, 0, len(t))
		for _, e := range t {
			out = append(out, convertValue(e))
		}
		return out
	}
	return v
}

func parse(data string) (p *parser, err error) {
	defer func() {
		if r := recover(); r != nil {
			if pErr, ok := r.(ParseError); ok {
				err = pErr
				return
			}
			panic(r)
		}
	}()

	if strings.HasPrefix(data, "\xff\xfe") || strings.HasPrefix(data, "\xfe\xff") {
		data = data[2:]
	} else if strings.HasPrefix(data, "\xef\xbb\xbf") {
		data = data[3:]
	}

	ex := 6
	if len(data) < 6 {
		ex = len(data)
	}
	if i := strings.IndexRune(data[:ex], 0); i > -1 {
		return nil, ParseError{
			Message:  "files cannot contain NULL bytes; probably using UTF-16; TOML files must be UTF-8",
			Position: Position{Line: 1, Start: i, Len: 1},
		}
	}

	p = &parser{
		keyInfo:   make(map[string]tomlType),
		mapping:   newTable(),
		lx:        lex(data),
		implicits: make(map[string]struct{}),
	}
	for {
		item := p.next()
		if item.typ == itemEOF {
			break
		}
		p.topLevel(item)
	}
	return p, nil
}

func (p *parser) panicErr(it item, err error) {
	panic(ParseError{Message: err.Error(), Position: it.pos, LastKey: p.current()})
}

func (p *parser) panicItemf(it item, format string, v ...interface{}) {
	panic(ParseError{Message: fmt.Sprintf(format, v...), Position: it.pos, LastKey: p.current()})
}

func (p *parser) panicf(format string, v ...interface{}) {
	panic(ParseError{Message: fmt.Sprintf(format, v...), Position: p.pos, LastKey: p.current()})
}

func (p *parser) next() item {
	it := p.lx.nextItem()
	if it.typ == itemError {
		if it.err != nil {
			panic(ParseError{Message: it.err.Error(), Position: it.pos, LastKey: p.current()})
		}
		p.panicItemf(it, "%s", it.val)
	}
	return it
}

func (p *parser) nextPos() item {
	it := p.next()
	p.pos = it.pos
	return it
}

func (p *parser) bug(format string, v ...interface{}) {
	panic(fmt.Sprintf("BUG: "+format+"\n\n", v...))
}

func (p *parser) expect(typ itemType) item {
	it := p.next()
	p.assertEqual(typ, it.typ)
	return it
}

func (p *parser) assertEqual(expected, got itemType) {
	if expected != got {
		p.bug("Expected '%s' but got '%s'.", expected, got)
	}
}

func (p *parser) topLevel(item item) {
	switch item.typ {
	case itemCommentStart:
		p.expect(itemText)
	case itemTableStart:
		name := p.nextPos()

		var key Key
		for ; name.typ != itemTableEnd && name.typ != itemEOF; name = p.next() {
			key = append(key, p.keyString(name))
		}
		p.assertEqual(itemTableEnd, name.typ)

		p.addContext(key, false)
		p.setType("", tomlTypeHash)
	case itemArrayTableStart:
		name := p.nextPos()

		var key Key
		for ; name.typ != itemArrayTableEnd && name.typ != itemEOF; name = p.next() {
			key = append(key, p.keyString(name))
		}
		p.assertEqual(itemArrayTableEnd, name.typ)

		p.addContext(key, true)
		p.setType("", tomlTypeArrayHash)
	case itemKeyStart:
		outerContext := p.context
		k := p.nextPos()
		var key Key
		for ; k.typ != itemKeyEnd && k.typ != itemEOF; k = p.next() {
			key = append(key, p.keyString(k))
		}
